import osimport sysfrom pathlib import Pathimport chardet# تنظیم مسیر پروژه (اگر اسکریپت رو در ریشه پروژه اجرا می‌کنید، نیازی به تغییر نیست)project_root = Path(".").resolve()views_dir = project_root / "resources" / "views"print(f"📂 پوشه مورد نظر: {views_dir}")if not views_dir.exists():    print("❌ خطا: پوشه resources/views پیدا نشد!")    sys.exit(1)# لیست فایل‌هایی که امروز تغییر کردن (برای کاهش ریسک، فقط همون‌ها رو اصلاح می‌کنیم)from datetime import datetimetoday = datetime.now().date()files_to_fix = []for file in views_dir.rglob("*.blade.php"):    mtime = datetime.fromtimestamp(file.stat().st_mtime).date()    if mtime == today:        files_to_fix.append(file)if not files_to_fix:    print("⚠️ هیچ فایل Blade ای امروز تغییر نکرده. اگر می‌خوای همه رو اسکن کنی، شرط تاریخ رو بردار.")    # برای امنیت، اگر چیزی پیدا نشد، از کاربر می‌پرسیم آیا همه رو بررسی کنه؟    answer = input("آیا همه فایل‌های Blade رو بررسی کنم؟ (yes/no): ")    if answer.lower() == 'yes':        files_to_fix = list(views_dir.rglob("*.blade.php"))    else:        sys.exit(0)print(f"🔍 تعداد فایل‌های مورد بررسی: {len(files_to_fix)}")fixed_count = 0failed_files = []for file in files_to_fix:    try:        # ۱. محتوای باینری فایل رو بخون        raw_data = file.read_bytes()                # ۲. انکدینگ رو با chardet تشخیص بده        result = chardet.detect(raw_data)        detected_encoding = result['encoding'] if result and result['encoding'] else 'utf-8'        confidence = result['confidence'] if result else 0                # ۳. سعی کن با انکدینگ تشخیص داده شده، محتوا رو به رشته تبدیل کنی        try:            text_content = raw_data.decode(detected_encoding)        except UnicodeDecodeError:            # اگر نشد، با utf-8 امتحان کن (با نادیده گرفتن خطاها)            text_content = raw_data.decode('utf-8', errors='ignore')            print(f"   ⚠️ خطا در دیکود با {detected_encoding}، از utf-8 با ignore استفاده شد.")                # ۴. دوباره با UTF-8 with BOM ذخیره کن (برای ویندوز و فارسی عالی است)        file.write_text(text_content, encoding='utf-8-sig')                print(f"   ✅ اصلاح شد: {file.name} (Encoding: {detected_encoding}, Confidence: {confidence:.2f})")        fixed_count += 1            except Exception as e:        print(f"   ❌ خطا در پردازش {file.name}: {e}")        failed_files.append(file.name)# گزارش نهاییprint("\n" + "="*50)print(f"✅ تعداد فایل‌های اصلاح‌شده: {fixed_count}")if failed_files:    print(f"❌ تعداد فایل‌های ناموفق: {len(failed_files)}")    print("لیست:", failed_files)print("="*50)